from pathlib import Path
import json
from lesson_authoring import entry as E
BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
P=[['希腊 psallein → psalmos','拨弦演奏 → 弦乐伴奏的歌，后来也指宗教诗歌']]
W=[E('psalm','英美 /sɑːm/','圣诗；《诗篇》中的一篇','可以唱出来、诵读出来的宗教诗歌，尤其指《圣经·诗篇》里的篇章。','古英语 psealm 接教会拉丁 psalmus，源于希腊 psalmos；再往前是 psallein“拨弦”。中古英语又受古法语 psalme 等形式影响，最后保留 ps- 拼写，但开头 p 不读。',P+[['教会拉丁 psalmus → 古英语 psealm','宗教诗歌'],['中古英语 salm / psalme，亦受古法语影响 → psalm','现代的圣诗、诗篇']],'sing a psalm 是唱圣诗；read a psalm 是读一篇诗篇。说 Psalm 23 时通常把 Psalm 大写，表示特定篇目；泛指一篇则写 a psalm。来源虽有乐器，现代不要求一定伴奏。','sing a psalm；read a psalm；the Book of Psalms。','poem 泛指诗，hymn 泛指赞美诗；psalm 尤其联系《诗篇》。它不是 palm“手掌”，虽然两词的许多常见读音只差开头 /s/ 与 /p/。',('The choir sang a psalm before the service ended.','礼拜结束前，唱诗班唱了一首圣诗。'),('The passage opens with a line from a psalm.','这段文字以《诗篇》中的一句话开头。'),sources=['https://www.etymonline.com/word/psalm','https://www.oxfordlearnersdictionaries.com/definition/english/psalm']),
E('psalmist','英美 /ˈsɑːmɪst/','圣诗作者；圣诗歌者','把 psalm 从“作品”转向创作或吟唱这种作品的人。','现代可看作 psalm + -ist；历史上有古法语 psalmiste、教会拉丁 psalmista 借入，接教会希腊 psalmistēs。不是只有英语内部加后缀这一条来历。',P+[['教会希腊 psalmizein → psalmistēs','唱圣诗 → 圣诗作者或歌者'],['教会拉丁 psalmista；古法语 psalmiste → 英语 psalmist','借入人的称谓']],'宗教评论里的 the psalmist 常指正在讨论的那首诗的作者。大写 the Psalmist 还常在传统语境中特指大卫；这是一种称谓，不能据此断言《诗篇》的每篇都由同一人创作。','the words of the psalmist；the psalmist writes；a biblical psalmist。','poet 是一般的诗人；psalmist 特指圣诗作者或歌者。-ist 指人，和 psalm“诗歌本身”区分开。',('The psalmist expresses both fear and hope in these lines.','圣诗作者在这些诗句里同时表达了恐惧与希望。'),('The lecturer compared the imagery used by two psalmists.','讲师比较了两位圣诗作者使用的意象。'),sources=['https://www.etymonline.com/word/psalmist','https://www.merriam-webster.com/dictionary/psalmist']),
E('psalter','英 /ˈsɔːltə/；美 /ˈsɔːltər/','《诗篇》集；圣诗集','把圣诗汇集成可以读、唱、翻阅的一本书。','接拉丁 psalterium：早先是弦乐器名，教会拉丁中转用于《诗篇》。再接希腊 psaltērion，源自动词 psallein“拨弦”。不能按英语 psalm 加 -er 理解成“唱歌的人”。',[['希腊 psallein → psaltērion','拨弦 → 弦乐器'],['拉丁 psalterium；教会拉丁的《诗篇》义','乐器名称转用于宗教歌曲集'],['古英语 (p)saltere；古法语 psaltier 等 → 中古英语 sauter / psauter → psalter','圣诗集、诗篇集']],'历史书或博物馆说明里的 an illuminated psalter，常是带精美装饰的《诗篇》手抄本。psalter 关注整部书或整套诗篇，不是其中单独一首歌。','a medieval psalter；an illuminated psalter；a page from a psalter。','psalm 是单篇，psalmist 是人，psalter 是集子。psalter 的 l 通常读出来；不要照搬 psalm 的读法。',('The museum displayed a beautifully decorated medieval psalter.','博物馆展出了一本装饰精美的中世纪《诗篇》集。'),('She found the verse in an old family psalter.','她在家传的一本旧圣诗集中找到了那句诗。'),sources=['https://www.etymonline.com/word/psalter','https://www.oxfordlearnersdictionaries.com/definition/english/psalter'])]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(x for x in m['roots']if x['id']=='C1143');c=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text())if x['id']=='C1143');keep={w['word']for w in W};excluded={w:'按用户要求暂略：低频圣乐技术或历史乐器名称。'for w in(set(r['family'])|set(c['family'])|set(c.get('unmatched',[])))-keep}
ROOT=[dict(id='C1143',meaning='拨弦、弹奏',core='想象手指轻拨琴弦：psall- 最初是这样一个动作。',image='拨弦伴奏的歌进入宗教语境，成为 psalm；写唱这些歌的人是 psalmist，集子则是 psalter。',intro='这组适合阅读文学、历史和宗教文化材料。核心是从弹弦乐器到诗歌，而不是把 psalm 当作“宗教”这个抽象意思随意拼接。现代圣诗可以有伴奏，也可以只是诵读。',forms='希腊 psallein“拨弦”产生 psalmos“弦乐伴奏的歌”和 psaltērion“弦乐器”。两条支线经拉丁进入英语，ps- 拼法保留，p 通常不发音。',branches=[['歌曲、篇章','psalm'],['作者、歌者','psalmist'],['整部诗歌集','psalter']],contrasts='psalter 的 -er 不是现代英语职业后缀，不能译成歌者；psalmist 才是人的称谓。',practice='用 psalm、psalmist、psalter 分别指一篇作品、创作者和装订成册的集子。',words=[w for w in r['family']if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/psalm','https://www.etymonline.com/word/psalter'])]
assert all(w['word']in m['owned_words']for w in W)
assert not(set(c['family'])|set(c.get('unmatched',[])))-set(ROOT[0]['words'])-set(excluded)
for w in W:assert len(w['examples'])>=2 and all(len(n)==2 and all(isinstance(x,str)and x for x in n)for n in w['history'])
for k,d in [('roots',ROOT),('words',W)]: (OUT/f'{k}_batch200_spec_186_psall.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
print('C1143',len(W),'new',len(ROOT[0]['words']),'retained')
